CREATE TABLE IF NOT EXISTS admin_settings (key TEXT PRIMARY KEY,value TEXT,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS site_visits (id SERIAL PRIMARY KEY,path TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS posts (id SERIAL PRIMARY KEY,title TEXT NOT NULL,title_en TEXT,content TEXT,content_en TEXT,image_url TEXT,category TEXT,published INTEGER DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS services (id SERIAL PRIMARY KEY,name TEXT NOT NULL,name_en TEXT NOT NULL,description TEXT,description_en TEXT,details TEXT,details_en TEXT,category TEXT NOT NULL CHECK(category IN ('massage','ayurveda','yoga','meditation')),duration_minutes INTEGER,format TEXT,format_en TEXT,price_cents INTEGER,tax_note TEXT,tax_note_en TEXT,price_verified INTEGER DEFAULT 0,published INTEGER DEFAULT 1,sort_order INTEGER DEFAULT 0,image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),CHECK(price_cents IS NULL OR price_cents>=0));
CREATE TABLE IF NOT EXISTS hours (id SERIAL PRIMARY KEY,weekday INTEGER NOT NULL UNIQUE CHECK(weekday BETWEEN 1 AND 7),opens TEXT,closes TEXT,closed INTEGER DEFAULT 0,image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS appointments (id SERIAL PRIMARY KEY,user_id TEXT,request_key TEXT,name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT,service_id INTEGER REFERENCES services(id) ON DELETE SET NULL,preferred_date DATE,time_window TEXT,consent INTEGER DEFAULT 0,privacy_snapshot TEXT,status TEXT DEFAULT 'requested' CHECK(status IN ('requested','confirmed','declined','cancelled','completed')),start_at TIMESTAMPTZ,end_at TIMESTAMPTZ,service_label TEXT,service_label_en TEXT,response TEXT,response_en TEXT,total_cents INTEGER,amount_cents INTEGER,tax_cents INTEGER,payment_kind TEXT DEFAULT 'full' CHECK(payment_kind IN ('full','deposit')),billing_verified INTEGER DEFAULT 0,terms_snapshot TEXT,cancel_requested INTEGER DEFAULT 0,payment_status TEXT DEFAULT 'unpaid',order_key TEXT UNIQUE,capture_key TEXT,paypal_order_id TEXT UNIQUE,paypal_capture_id TEXT UNIQUE,paypal_mode TEXT,paypal_client_hash TEXT,order_started_at TIMESTAMPTZ,paid_at TIMESTAMPTZ,checked_at TIMESTAMPTZ,email_state TEXT DEFAULT 'not_sent',image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,request_key),CHECK(end_at IS NULL OR start_at IS NULL OR end_at>start_at),EXCLUDE USING gist (tstzrange(start_at,end_at,'[)') WITH &&) WHERE (status IN ('confirmed','completed')));